from common import p,step,svg,text,line,graph
import math

def fishhook(x1,y1,cx,cy,x2,y2):
    # The single short barb distinguishes a one-electron arrow from a full arrowhead.
    dx,dy=x2-cx,y2-cy
    distance=math.hypot(dx,dy);dx/=distance;dy/=distance
    return (f'<path d="M{x1} {y1} Q{cx} {cy} {x2} {y2}" fill="none" stroke="#a45423" stroke-width="2.3"/>'
            +line(x2,y2,x2-9*dx+4*dy,y2-9*dy-4*dx,'#a45423',2.3))

def add_radicals(b):
    code='R3.3'
    def mc(diff,title,stem,correct,distractors,reason,**kw):
        return b.add(code,'sl',diff,title,stem,correct=correct,distractors=distractors,reasoning=reason,**kw)
    def q(diff,title,stem,*parts,**kw):
        return b.add(code,'sl',diff,title,stem,parts=list(parts),**kw)
    mc('easy','Recognising a radical','Which feature defines a radical?', 'It has at least one unpaired electron.',['It must have a positive electric charge.','It must have an incomplete atomic nucleus.','It must contain an oxygen atom.'],'A radical is identified by an unpaired electron. A radical can be neutral or charged and need not contain oxygen.')
    mc('medium','A dot is not a charge',r'Compare $\mathrm{Cl^{\bullet}}$ and $\mathrm{Cl^-}$. Which statement is correct?',r'$\mathrm{Cl^{\bullet}}$ is neutral with an unpaired electron; $\mathrm{Cl^-}$ is an anion.',['Both symbols represent chloride ions.','The dot means the atom has lost a proton.',r'$\mathrm{Cl^{\bullet}}$ has one more electron than $\mathrm{Cl^-}$.'],r'A chlorine radical has the electrons of a neutral chlorine atom, with an unpaired electron. Chloride has gained one electron and has a full valence shell.')
    prompt=svg(text(400,30,'Bond breaking in chlorine',20)+text(260,180,'Cl',30)+text(440,180,'Cl',30)+line(284,170,418,170)+text(400,285,'Show one electron moving to each atom.',17),800,330)
    worked=svg(text(220,90,'Cl',28)+text(400,90,'Cl',28)+line(246,80,374,80)+fishhook(304,77,265,15,232,60)+fishhook(314,77,350,15,389,60)+text(400,200,'Cl·  +  ·Cl',28)+text(400,260,'One single-barbed arrow to each atom',17),800,320)
    q('medium','Drawing homolytic bond fission',r'Ultraviolet light causes homolytic fission of a $\mathrm{Cl-Cl}$ bond.',p('Draw the electron movement and write the products.',step('Use two single-barbed arrows from the bonding pair, one towards each chlorine atom.'),step(r'$\mathrm{Cl_2\xrightarrow{UV}2Cl^{\bullet}}$; both products are neutral radicals.')),p('Name this step in an alkane chlorination chain reaction.',step('Initiation.')),diagram=prompt,worked=worked)
    q('medium','Why light starts the chain',r'A mixture of methane and chlorine is exposed to ultraviolet light.',p('Explain the role of ultraviolet light in initiation.',step('A chlorine molecule absorbs sufficient energy to break its covalent bond.'),step('Homolytic cleavage forms two chlorine radicals that can begin the chain.')),p('Explain why describing the process as chloride-ion production is incorrect.',step('Each chlorine receives one bonding electron; there is no transfer of both electrons to one atom, so neutral radicals form rather than ions.')))
    q('medium','Completing a propagation pair',r'The first propagation step in methane chlorination is $\mathrm{Cl^{\bullet}+CH_4\rightarrow HCl+CH_3^{\bullet}}$.',p('Write the second propagation step and explain why the sequence can repeat.',step(r'$\mathrm{CH_3^{\bullet}+Cl_2\rightarrow CH_3Cl+Cl^{\bullet}}$.'),step('The chlorine radical consumed in the first step is regenerated in the second and can attack another methane molecule.')),p('State the net equation for these two steps.',step(r'$\mathrm{CH_4+Cl_2\rightarrow CH_3Cl+HCl}$.')))
    mc('medium','Which step terminates a chain?',r'Which equation represents termination in methane chlorination?',r'$\mathrm{CH_3^{\bullet}+Cl^{\bullet}\rightarrow CH_3Cl}$',[r'$\mathrm{Cl_2\xrightarrow{UV}2Cl^{\bullet}}$',r'$\mathrm{Cl^{\bullet}+CH_4\rightarrow HCl+CH_3^{\bullet}}$',r'$\mathrm{CH_3^{\bullet}+Cl_2\rightarrow CH_3Cl+Cl^{\bullet}}$'],r'Two radicals combine and no radical remains in the product. Initiation produces radicals; propagation consumes a radical but produces another.')
    q('medium','Three ways to end a methane chain',r'A methane chlorination mixture contains chlorine and methyl radicals.',p('Write three different radical-combination termination equations.',step(r'$\mathrm{Cl^{\bullet}+Cl^{\bullet}\rightarrow Cl_2}$.'),step(r'$\mathrm{CH_3^{\bullet}+Cl^{\bullet}\rightarrow CH_3Cl}$.'),step(r'$\mathrm{CH_3^{\bullet}+CH_3^{\bullet}\rightarrow C_2H_6}$.')),p('Explain why one termination pathway gives a product with more carbon atoms than the starting alkane molecule.',step('Two one-carbon methyl radicals combine to make one two-carbon ethane molecule.')))
    q('medium','Cancelling the chain carriers',r'Ethane bromination includes $\mathrm{Br^{\bullet}+C_2H_6\rightarrow HBr+C_2H_5^{\bullet}}$ and $\mathrm{C_2H_5^{\bullet}+Br_2\rightarrow C_2H_5Br+Br^{\bullet}}$.',p('Add the equations and cancel intermediates to obtain the overall equation.',step(r'Cancel $\mathrm{Br^{\bullet}}$ and $\mathrm{C_2H_5^{\bullet}}$ appearing once on each side.','M1'),step(r'$\mathrm{C_2H_6+Br_2\rightarrow C_2H_5Br+HBr}$.')),p('Explain why the net equation alone does not reveal the reaction mechanism.',step('It shows the overall atom balance but omits the radical intermediates and separate elementary steps.')))
    q('hard','A supplied atmospheric radical cycle',r'Consider the simplified cycle $\mathrm{Cl^{\bullet}+O_3\rightarrow ClO^{\bullet}+O_2}$, followed by $\mathrm{ClO^{\bullet}+O\rightarrow Cl^{\bullet}+O_2}$. The symbol O denotes an oxygen atom.',p('Deduce the overall reaction.',step(r'Cancel the chlorine-containing radicals.','M1'),step(r'$\mathrm{O_3+O\rightarrow 2O_2}$.')),p('Identify the species regenerated and explain why a small amount can lead to much ozone loss.',step(r'$\mathrm{Cl^{\bullet}}$ is regenerated.'),step('It can begin another cycle instead of being consumed in the net reaction, until a process removes it from the cycle.')),question_type='data-based')
    q('medium','Which bond is easier to split?',r'A molecule contains C–Cl and C–F bonds with representative bond enthalpies of $330$ and $485\,\mathrm{kJ\,mol^{-1}}$, respectively. Assume absorbed radiation can break a bond if sufficient energy is available.',p('Predict which bond is more readily broken by a limited-energy supply and identify the halogen radical produced.',step('The C–Cl bond is weaker and requires less energy to break.'),step('Its homolytic cleavage produces a chlorine radical.')),p('Explain why this conclusion does not imply every photon breaks a bond.',step('Absorption and a suitable energy-transfer pathway are also required; a photon that is not absorbed cannot cause that cleavage.')),question_type='data-based')
    q('medium','Monochlorination of propane',r'Propane reacts with a small amount of chlorine under ultraviolet light. Consider only products in which exactly one hydrogen is replaced by chlorine.',p('Draw or give condensed formulas and names for the two constitutional products.',step(r'$\mathrm{CH_3CH_2CH_2Cl}$, 1-chloropropane.'),step(r'$\mathrm{CH_3CHClCH_3}$, 2-chloropropane.')),p('Explain why replacing a hydrogen at either end does not give a third product.',step('The two terminal carbon positions are equivalent by the symmetry of propane.')))
    mc('medium','Equivalent hydrogen positions',r'How many different constitutional products result from replacing exactly one hydrogen in butane with chlorine?',r'$2$',[r'$1$',r'$3$',r'$4$'],r'The two end carbons are equivalent and the two inner carbons are equivalent. Substitution therefore gives 1-chlorobutane and 2-chlorobutane. Count constitutional products only.')
    q('hard','A deliberately statistical substitution model',r'For this model only, assume each C–H bond in 2-methylpropane has equal probability of radical substitution. There are nine hydrogens attached to primary carbons and one attached to the central carbon. Consider only single substitution.',p('Predict the ratio of the primary-position product to the central-position product.',step('There are nine available primary-position H atoms for every one central-position H atom.','M1'),step('The predicted ratio is 9:1 under the stated equal-reactivity model.')),p('Explain why a real experiment could give a different ratio without violating atom conservation.',step('The model assumes equal probabilities, but chemically different C–H sites need not react equally readily.'),step('Atom conservation restricts the formulas of products, not their relative yields.')),question_type='data-based')
    q('medium','Further substitution',r'Chloromethane remains in a chlorination mixture containing chlorine radicals and chlorine.',p('Write two propagation equations that produce dichloromethane.',step(r'$\mathrm{Cl^{\bullet}+CH_3Cl\rightarrow HCl+CH_2Cl^{\bullet}}$.'),step(r'$\mathrm{CH_2Cl^{\bullet}+Cl_2\rightarrow CH_2Cl_2+Cl^{\bullet}}$.')),p('Explain why isolating only chloromethane can be difficult.',step('The first organic product still contains C–H bonds and can undergo further radical substitution, producing a mixture.')))
    mc('medium','Favouring a monosubstituted product',r'Which change is most likely to reduce repeated chlorination when preparing chloromethane from methane?', 'Use a large excess of methane relative to chlorine.',['Use a large excess of chlorine relative to methane.','Leave the product mixture under ultraviolet light with excess chlorine for longer.','Add chloromethane as the only organic starting material.'],r'An excess of methane makes radical encounters with unreacted methane more likely relative to encounters with chlorinated products, favouring first substitution. It does not guarantee a perfectly pure product.')
    q('hard','Why termination is a different encounter',r'In a chain mixture, stable alkane molecules greatly outnumber radicals.',p('Compare the reactants in a typical propagation step and a termination step.',step('Propagation typically involves one radical reacting with a stable molecule.'),step('Termination by combination requires two radicals to meet.')),p('Explain why low radical concentration can allow many propagation events before a radical is terminated.',step('A radical is far more likely to encounter an abundant stable reactant than another scarce radical.'),step('Such propagation encounters regenerate a radical, maintaining the chain.')))
    pts=[(0,0),(10,0.1),(20,0.2),(30,2.5),(40,5.0),(50,7.5),(60,8.0),(70,8.1)]
    q('medium','Light-on and light-off evidence',r'A chlorination experiment gives the product amounts shown. The ultraviolet lamp is switched on at $20\,\mathrm{s}$ and off at $50\,\mathrm{s}$; other conditions are unchanged.',p('Describe the evidence that irradiation promotes the reaction.',step('The product accumulates much more quickly between 20 s and 50 s than before irradiation or long after the lamp is switched off.')),p('Explain the observation using radicals and suggest why a little product appears after 50 s.',step('Light generates radicals by initiation.'),step('Radicals present at switch-off can continue propagation briefly before they are removed by termination.')),diagram=graph('Product amount during irradiation','Time / s','Product amount / arbitrary units',pts),question_type='data-based')
    q('hard','Evidence from a radical trap',r'A reagent T reacts rapidly with an alkyl radical by $\mathrm{R^{\bullet}+T\rightarrow RT^{\bullet}}$. The product radical $\mathrm{RT^{\bullet}}$ is stable enough that it does not propagate the halogenation chain. Adding T sharply decreases the organic halide yield.',p('Explain the decrease in yield.',step('T intercepts reactive alkyl radicals before they react with halogen.'),step('The trapped radical does not generate the halogen radical needed to continue the chain.')),p('Explain why a radical can remain present even when the chain is inhibited.',step('An unpaired electron defines a radical, but the supplied information says this particular trapped radical does not carry the chain efficiently.')),question_type='data-based')
    q('hard','Isotope labels and atom tracking',r'One propagation sequence starts when $\mathrm{Cl^{\bullet}}$ removes the D atom from $\mathrm{CH_3D}$; D is an isotope of hydrogen. The resulting carbon radical then reacts with $\mathrm{Cl_2}$.',p('Write both propagation equations with the isotope label preserved.',step(r'$\mathrm{Cl^{\bullet}+CH_3D\rightarrow DCl+CH_3^{\bullet}}$.'),step(r'$\mathrm{CH_3^{\bullet}+Cl_2\rightarrow CH_3Cl+Cl^{\bullet}}$.')),p('Identify which product contains the original D atom and explain why it cannot also appear in the organic product.',step(r'DCl contains the D atom.'),step('The single labelled atom has already transferred to DCl; adding it to chloromethane as well would violate atom conservation.')))
    q('medium','A radical is regenerated',r'In methane chlorination, a chlorine radical is consumed by methane and then re-formed when the methyl radical reacts with chlorine.',p('Explain why the chlorine radical does not appear in the net propagation equation.',step('It appears as a reactant in one step and as a product in the other, so it cancels.'),step('It acts as a chain carrier through the sequence.')),p('Explain why this does not mean the chain must continue forever.',step('Radicals can be removed by termination or other trapping processes; reactants can also become depleted.')))
    mc('easy','One electron or two?',r'What kind of arrow convention should show the transfer of one electron during homolytic fission?', 'A curved arrow with one barb.',['A curved arrow with a full two-barbed head.','An equilibrium arrow between concentrations.','A straight line with no direction.'],'A single-barbed or fish-hook arrow tracks one electron. A full curly-arrow head conventionally tracks a pair of electrons.')
    q('medium','Correcting an initiation equation',r'A proposed initiation equation is $\mathrm{Cl_2\rightarrow Cl^++Cl^-}$. The student labels the process homolytic fission.',p('Identify the error and write the intended homolytic equation.',step('The written equation transfers both bonding electrons to one atom and describes heterolysis.'),step(r'Homolysis is $\mathrm{Cl_2\rightarrow 2Cl^{\bullet}}$, normally with UV or heat indicated.')),p('Compare the total charge on each side of both equations.',step('Both equations have total charge zero on each side. Charge conservation alone therefore cannot distinguish the two modes of fission.')))
    q('hard','What a light experiment can establish',r'Two sealed reaction vessels have the same initial methane and chlorine amounts and temperature. One is irradiated and one is kept dark. After ten minutes the irradiated vessel contains more chloromethane.',p('State a supported conclusion and one conclusion that is not established by this single measurement.',step('Irradiation led to more product over the measured time under these conditions.'),step('It does not by itself prove the final equilibrium composition or maximum eventual yield differs.')),p('Suggest a control needed to isolate the effect of light.',step('Keep temperature the same, since the lamp might otherwise heat the irradiated vessel; identical concentrations, vessels and times are also relevant.')),question_type='data-based')
    mc('medium','The methyl radical electron count',r'Which description of $\mathrm{CH_3^{\bullet}}$ is correct?', 'Carbon has three C–H bonds and one unpaired electron.',['Carbon has four C–H bonds and no unpaired electron.','Carbon has three C–H bonds and a complete lone pair with a negative charge.','The dot represents a hydrogen nucleus.'],r'Three bonding pairs surround the carbon and one electron is unpaired. The methyl radical is neutral; it is distinct from the methyl anion, which has a lone pair and negative charge.')
    q('medium','Thermal initiation',r'Bromine molecules undergo homolytic fission when supplied with sufficient thermal energy.',p('Write the initiation equation and identify the species that can attack an alkane.',step(r'$\mathrm{Br_2\xrightarrow{heat}2Br^{\bullet}}$.'),step('A bromine radical can remove a hydrogen atom from an alkane.')),p('Explain why heat can initiate a reaction without appearing as a chemical reactant in the net equation.',step('Heat supplies energy needed to overcome the bond-breaking barrier; it is not a source of atoms that need to appear in the chemical equation.')))
    mc('medium','Does each product require a new photon?',r'Why can a chain reaction produce many halogenoalkane molecules after relatively few successful photochemical initiation events?', 'Propagation regenerates a radical that can start another cycle.',['Each photon becomes one carbon atom.','Radicals are permanent and cannot terminate.','The halogen molecule acts only as a solvent.'],r'A successful initiation event creates radicals. Repeated propagation can form many products while regenerating a chain carrier, until termination removes radicals.')
    q('hard','Ethane as a mechanistic clue',r'A small quantity of ethane is detected during methane chlorination even though no ethane was added initially.',p('Suggest a radical step that accounts for the observation.',step(r'$\mathrm{CH_3^{\bullet}+CH_3^{\bullet}\rightarrow C_2H_6}$.')),p('Classify the step and explain why the observation supports a radical mechanism.',step('It is termination: two radicals combine to give a non-radical product.'),step('The two-carbon by-product is consistent with recombination of one-carbon methyl radicals, a species proposed in the chain.')),p('Explain why this observation is evidence rather than absolute proof of a unique mechanism.',step('Other plausible pathways would have to be excluded; a mechanism is supported by converging evidence rather than one observation alone.')),question_type='data-based')
    q('hard','Exothermic overall, initiation still needed',r'Two propagation steps have enthalpy changes of $+12\,\mathrm{kJ\,mol^{-1}}$ and $-98\,\mathrm{kJ\,mol^{-1}}$ for one complete cycle.',p('Calculate the overall propagation-cycle enthalpy change.',step(r'$\Delta H=12-98=-86\,\mathrm{kJ\,mol^{-1}}$.','M1')),p('Explain why the negative total does not remove the need for initiation.',step('The net enthalpy change describes the energy difference between reactants and products.'),step('A barrier still has to be overcome to form the initial radicals; an exothermic reaction can be slow without a suitable initiation pathway.')),question_type='data-based')
    q('medium','Substitution rather than addition',r'The overall reaction is $\mathrm{C_2H_6+Cl_2\rightarrow C_2H_5Cl+HCl}$.',p('Explain why this is a substitution reaction.',step('One hydrogen on the alkane is replaced by chlorine.'),step('A small molecule, HCl, forms; chlorine does not simply add across a multiple bond in the starting alkane.')),p('Explain why the carbon skeleton is unchanged in the main organic product.',step('The propagation sequence replaces a C–H connection with C–Cl without breaking the carbon–carbon skeleton.')))
    q('hard','Auditing a proposed radical sequence',r'A student proposes: I, $\mathrm{Cl^{\bullet}+CH_4\rightarrow HCl+CH_3^{\bullet}}$; II, $\mathrm{CH_3^{\bullet}+Cl^{\bullet}\rightarrow CH_3Cl}$. The student calls both steps propagation.',p('Assess the classification of each step.',step('I is propagation: one radical is consumed and another is formed.'),step('II is termination: two radicals are consumed and no radical product is formed.')),p('Replace II with a valid second propagation step and explain the practical consequence.',step(r'$\mathrm{CH_3^{\bullet}+Cl_2\rightarrow CH_3Cl+Cl^{\bullet}}$.'),step('This restores the chlorine chain carrier and allows another propagation cycle.')))
    assert len(b.questions)==90
